e  m{0}}\int_t ho_f(t, { m \omega})\phi ig(	au(\|{ m \omega}\|_2^{-1}{ m \omega}^{	op}{ m x} - t) ig)\Lambda(\mathrm{d}t, \mathrm{d}{ m \omega}) = f^{\mathsf{approx}}({ m x}), \end{align*} where  egin{align} ho_f(t, { m \omega}) \coloneqq  rac{\gamma_{{ m \omega}, 	heta_f({ m \omega})}(t)\|{ m \omega}\|_2|F_f({ m \omega})|\mathrm{d}t\mathrm{d}{ m \omega}}{\Lambda(\mathrm{d}t, \mathrm{d}{ m \omega})}. \end{align} Substitution into \eqref{eq:lem_expression} immediately establishes the advertised result \eqref{eq:expression}. To finish up, it suffices to note the following two facts:  egin{itemize} \item Combining \eqref{eq:defn-Lambda} and \eqref{eq:defn-rho-f}, we have $$ |ho_f(t, { m \omega})|\le  rac{|\gamma_{{ m \omega}, 	heta_f({ m \omega})}(t)|\|{ m \omega}\|_2|F_f({ m \omega})|}{\Gamma_{\mathcal{F}}^{-1}\,\|{ m \omega}\|_2F^{\mathsf{sup}}({ m \omega})} \overset{	ext{(a)}}{\le} \Gamma_{\mathcal{F}}\overset{	ext{(b)}}{\le} 3\Big(C_{\mathcal{F}} - \sup_{	ilde{f}\in\mathcal{F}}|	ilde{f}({ m 0})| \Big), $$ where (a) follows from \eqref{eq:proof-lem-expression-int-gamma} and (b) from \eqref{eq:UB-Gamma-F1}. \item Substituting \eqref{eq:defn-rho-f} into the expectation of $|ho_f(t,  m{\omega})|$ gives  egin{align*} \mathbb{E}_{(t,  m{\omega}) \sim \Lambda} ig[|ho_f(t,  m{\omega})| ig] &=\int_{{ m \omega}
